mapper.select:
select t.modal_bean,t.modal_bean modalBean,t.modal_type,t.modal_type modalType,t.modal_id,t.modal_id
modalId,t.modal_name,t.modal_name modalName,t.status_cd,t.status_cd statusCd
from dt_modal t
where 1 =1

    and t.modal_bean= #{modalBean}


    and t.modal_type= #{modalType}


    and t.modal_id= #{modalId}


    and t.modal_name= #{modalName}


    and t.status_cd= #{statusCd}

order by t.create_time desc

    limit #{page}, #{row}

